def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'D'
    if n == 1:
        return 'C'
    if n >= 99:
        return 'D'

    opp_R2 = history[1][1]

    # Count retaliations: our D followed by opponent D
    retaliations = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i+1][1] == 'D':
            retaliations += 1

    if opp_R2 == 'D':
        # CAUTIOUS mode
        if n < 19:
            return 'C'
        if n == 19:
            return 'D'
        if n == 20:
            return 'C'
        if n >= 21:
            opp_R21 = history[20][1]
            if opp_R21 == 'D':
                return 'C'
            else:
                if (n + 1) % 2 == 1:
                    return 'D'
                else:
                    return 'C'
    else:
        # AGGRESSIVE mode
        if retaliations > 0:
            return 'C'
        if n == 2:
            return 'D'
        if n == 3:
            return 'D'
        if n >= 4 and n <= 13:
            return 'C'
        if history[-1][1] == 'D':
            return 'C'
        r = n + 1
        if r >= 15 and (r - 15) % 5 == 0:
            return 'D'
        return 'C'
